using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Infrastructure;using Microsoft.EntityFrameworkCore.Migrations;using VeterinaryHospitalManagement.Web.Data;
namespace VeterinaryHospitalManagement.Tests.Integration.Scheduling;
public sealed class AppointmentMigrationScriptTests
{
 [Fact]public void AddAppointments_creates_locked_schema_and_rolls_back(){using var db=new ApplicationDbContext(new DbContextOptionsBuilder<ApplicationDbContext>().UseSqlServer("Server=localhost;Database=x;Integrated Security=True;TrustServerCertificate=True").Options);var migrations=db.Database.GetMigrations().ToList();var before=Assert.Single(migrations,x=>x.EndsWith("_AddCatalogs"));var current=Assert.Single(migrations,x=>x.EndsWith("_AddAppointments"));var migrator=db.GetService<IMigrator>();var up=migrator.GenerateScript(before,current);Assert.Contains("CREATE TABLE [Appointments]",up);Assert.Contains("CK_Appointments_TimeRange",up);Assert.Contains("CK_Appointments_Status",up);Assert.Contains("CK_Appointments_CancellationReason",up);Assert.Contains("CREATE UNIQUE INDEX [UQ_Appointments_AppointmentNumber]",up);Assert.Contains("IX_Appointments_VeterinarianId_Status_StartAt",up);Assert.Contains("IX_Appointments_PetId_Status_StartAt",up);Assert.Contains("ON DELETE NO ACTION",up);Assert.Contains("DROP TABLE [Appointments]",migrator.GenerateScript(current,before));}
}
